    @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);load();if(saved!=null&&saved.getBundle("rotation")!=null)rotationEditor=new AmbientRotationEditor(this,saved.getBundle("rotation"),this::closeRotation);if(saved!=null&&saved.getBundle("playlist")!=null)playlistEditor=new SoundPlaylistEditor(this,saved.getBundle("playlist"),this::closePlaylist);if(saved!=null&&saved.containsKey("audioImport")){audioImport=SoundImports.find(saved.getString("audioImport"));if(audioImport==null)localError="Audio import was interrupted. Choose the file again.";}if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::back);render();reader.execute(()->{for(String name:new String[]{"Rain","Ocean","Fireplace","Wind","My audio"}){Bitmap bitmap=null;try(java.io.InputStream stream=getAssets().open("sound-art/"+asset(name)+".png")){BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=2;bitmap=BitmapFactory.decodeStream(stream,null,options);}catch(Exception ignored){}Bitmap result=bitmap;runOnUiThread(()->{if(!isDestroyed()&&result!=null){artwork.put(name,result);showArt();}});}});}
